return [
 { json: { name: 'Ana',  email: 'ana@acme.example' } },
 { json: { name: 'Bo',   email: 'not-an-email' } },
 { json: { name: 'Cid',  email: 'cid@x.example' } },
 { json: { name: 'Ana2', email: 'ana@acme.example' } },
 { json: { name: '',     email: 'no@name.example' } },
 { json: { name: 'Dee',  email: 'dee@y.example' } }
];

const seen = new Set();
return $input.all().map(({ json: d }) => {
  const badEmail = !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(d.email || '');
  const noName = !d.name;
  const dup = !badEmail && seen.has(d.email);
  if (!badEmail) seen.add(d.email);
  const reason = badEmail ? 'invalid email' : noName ? 'missing name'
    : dup ? 'duplicate email' : 'clean';
  return { json: { ...d, ok: !(badEmail || noName || dup), reason } };
});

const d = $json;
return { json: { status: 'cleane',
  summary: `${d.name} <${d.email}>` } };

const d = $json;
return { json: { status: 'alerted',
  alert: `${d.email || '(no email)'}: ${d.reason}` } };

// One owner-facing summary per run. Keep AFTER Merge — two
// branches fed in directly would execute this node twice.
const items = $input.all().map(i => i.json);
const ok = items.filter(i => i.status === 'cleane');
const bad = items.filter(i => i.status === 'alerted');
const detail = bad.map(i => '  - ' + (i.alert || i.summary || '')).join('\n');
return [{ json: { status: 'digest',
  summary: `Run complete: ${ok.length} item(s) cleaned, ${bad.length} alert(s)`,
  detail } }];
